"""The SRUM parser: decoding of the rows, the two sources, the ids, the counts, the damage. Run in the worker's image.

**What is proven here and what is not.** An ESE database cannot be generated by a small writer, so the file-level path
(libesedb opening a real ``SRUDB.dat``) is not proven by these tests. They run the parser over *faked* libesedb objects
(a database, its tables, their records: the few members the parser uses) behind a real 4 KiB ESE header written
here, and they test the decoding functions on their own. The real database was read by hand, in the worker's
image, against the Apache-2.0 test file of the Plaso project, and the same check runs here when ``NIK_SRUDB_SAMPLE``
names such a file.
"""

from __future__ import annotations

import io
import json
import math
import os
import struct
import sys

import pytest

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, HERE)

from nik_forensics import parsers  # noqa: E402
from nik_forensics.context import Context  # noqa: E402
from nik_forensics.parsers import BadLocator, ViewError, srum  # noqa: E402

NET, APPS = srum.TABLES["network"][0], srum.TABLES["apps"][0]
OLE_2017 = 43044.48055555556  # 2017-11-05 11:32 UTC, the SRUM sample's first hour


# --------------------------------------------------------------------------- #
# Faked libesedb objects: only the members the parser uses                    #
# --------------------------------------------------------------------------- #
class Column:
    def __init__(self, name: str, kind: int) -> None:
        self.name, self.type = name, kind


class Record:
    def __init__(self, values: list[bytes | None]) -> None:
        self.values = values

    def get_value_data(self, index: int) -> bytes | None:
        return self.values[index]


class Table:
    def __init__(self, name: str, columns: list[tuple[str, int]], rows: list) -> None:
        self.name = name
        self._columns = [Column(*column) for column in columns]
        self.rows = rows
        self.number_of_columns = len(columns)

    @property
    def number_of_records(self) -> int:
        return len(self.rows)

    def get_column(self, index: int) -> Column:
        return self._columns[index]

    def get_record(self, index: int) -> Record:
        row = self.rows[index]
        if isinstance(row, Exception):
            raise row
        return Record(row)


class Db:
    def __init__(self, tables: list[Table]) -> None:
        self.tables = tables
        self.number_of_tables = len(tables)
        self.closed = False

    def get_table(self, index: int) -> Table:
        return self.tables[index]

    def close(self) -> None:
        self.closed = True


def i32(value: int) -> bytes:
    return struct.pack("<i", value)


def i64(value: int) -> bytes:
    return struct.pack("<q", value)


def dbl(value: float) -> bytes:
    return struct.pack("<d", value)


def utf16(text: str) -> bytes:
    return text.encode("utf-16-le") + b"\x00\x00"


SID_SYSTEM = bytes([1, 1, 0, 0, 0, 0, 0, 5]) + struct.pack("<I", 18)
SID_USER = bytes([1, 5, 0, 0, 0, 0, 0, 5]) + struct.pack("<5I", 21, 1, 2, 3, 1001)
IDS = Table(
    srum.ID_TABLE,
    [("IdType", 2), ("IdIndex", 4), ("IdBlob", 11)],
    [
        [b"\x00", i32(153), utf16("DiagTrack")],
        [b"\x00", i32(19), utf16(r"\device\harddiskvolume3\windows\system32\svchost.exe")],
        [b"\x03", i32(4), SID_SYSTEM],
        [b"\x03", i32(7), SID_USER],
    ],
)
NET_COLUMNS = [
    ("AutoIncId", 4),
    ("TimeStamp", 8),
    ("AppId", 4),
    ("UserId", 4),
    ("InterfaceLuid", 15),
    ("L2ProfileId", 4),
    ("L2ProfileFlags", 4),
    ("BytesSent", 15),
    ("BytesRecvd", 15),
]
APP_COLUMNS = [
    ("AutoIncId", 4),
    ("TimeStamp", 8),
    ("AppId", 4),
    ("UserId", 4),
    ("ForegroundCycleTime", 15),
    ("BackgroundCycleTime", 15),
    ("ForegroundBytesRead", 15),
    ("ForegroundBytesWritten", 15),
    ("FutureColumn", 4),
]
LUID = (6 << 48) | (0x8001 << 24)


def net_row(row_id: int, days: float | None, app: int, user: int, sent: int, received: int) -> list[bytes | None]:
    return [
        i32(row_id),
        dbl(days) if days is not None else None,
        i32(app),
        i32(user),
        i64(LUID),
        i32(0),
        i32(0),
        i64(sent),
        i64(received),
    ]


def app_row(row_id: int, days: float, app: int, user: int) -> list[bytes | None]:
    return [i32(row_id), dbl(days), i32(app), i32(user), i64(5_000_000), i64(0), i64(2048), i64(512), i32(77)]


def ese_file(tmp_path, state: int = 3, kind: int = 0) -> str:
    head = bytearray(4096)
    head[4:8] = srum.ESE_SIGNATURE
    struct.pack_into("<I", head, 12, kind)
    struct.pack_into("<I", head, 52, state)
    struct.pack_into("<I", head, 236, 4096)
    path = tmp_path / "SRUDB.dat"
    path.write_bytes(bytes(head))
    return str(path)


def said(tmp_path, tables: list[Table], monkeypatch, state: int = 3) -> list[dict]:
    path = ese_file(tmp_path, state)
    db = Db(tables)
    monkeypatch.setattr(srum, "_open_db", lambda _path: db)
    out = io.BytesIO()
    srum.parse(path, Context(out, {"host": "WKS-1"}), srum.SOURCES[0])
    assert db.closed
    return [json.loads(line) for line in out.getvalue().splitlines() if line]


def of(found: list[dict], kind: str) -> list[dict]:
    return [event for event in found if event["t"] == kind]


def both() -> list[Table]:
    return [
        IDS,
        Table(
            NET,
            NET_COLUMNS,
            [net_row(3495, OLE_2017, 153, 4, 2076, 10), net_row(3496, OLE_2017 + 1 / 24, 19, 7, 5, 1 << 40)],
        ),
        Table(APPS, APP_COLUMNS, [app_row(22129, OLE_2017, 19, 7)]),
    ]


# --------------------------------------------------------------------------- #
def test_the_module_declares_what_the_worker_needs():
    assert (srum.NAME, srum.VERSION, srum.KIND) == ("srum", "1", "endpoint")
    assert srum.SOURCES == ("windows.network.srum-network", "windows.network.srum-apps")
    assert parsers.by_source("endpoint", "windows.network.srum-apps") is srum


def test_each_table_gives_records_of_its_own_source(tmp_path, monkeypatch):
    found = said(tmp_path, both(), monkeypatch)
    records = of(found, "r")
    assert [(r["src"], r["key"]) for r in records] == [
        ("windows.network.srum-network", "srum:WKS-1:network:3495"),
        ("windows.network.srum-network", "srum:WKS-1:network:3496"),
        ("windows.network.srum-apps", "srum:WKS-1:apps:22129"),
    ]
    first = records[0]
    assert first["ts"] == 1_509_881_520_000 and first["type"] == "srum-network"
    assert first["username"] == "S-1-5-18" and first["host"] == "WKS-1"
    assert first["loc"] == {"table": "network", "index": 0, "id": 3495}
    data = first["data"]
    assert (data["app"], data["app_id"], data["user"], data["user_id"]) == ("DiagTrack", 153, "S-1-5-18", 4)
    assert (data["bytes_sent"], data["bytes_received"], data["bytes_total"]) == (2076, 10, 2086)
    assert (
        data["interface_luid"] == f"0x{LUID:016x}" and data["interface_type"] == 6 and data["interface_index"] == 0x8001
    )
    assert (data["profile_id"], data["profile_flags"]) == (0, 0)
    assert first["summary"] == "DiagTrack: 2.0 KB sent, 10 B received"
    assert (
        records[1]["data"]["user"].startswith("S-1-5-21-1-2-3-1001")
        and records[1]["ts"] == 1_509_881_520_000 + 3_600_000
    )
    apps = records[2]["data"]
    assert apps["app"].endswith("svchost.exe") and apps["foreground_cycle_time"] == 5_000_000
    assert (apps["foreground_bytes_read"], apps["foreground_bytes_written"]) == (2048, 512)
    assert apps["future_column"] == 77  # a column the parser does not know is kept under its name
    end = of(found, "end")[0]
    assert end["in_file"] == 3 and end["read"] == 3 and not of(found, "skip") and not of(found, "note")


def test_a_row_without_a_time_or_with_an_id_the_table_does_not_hold_is_kept_and_counted(tmp_path, monkeypatch):
    tables = [
        IDS,
        Table(
            NET,
            NET_COLUMNS,
            [net_row(1, None, 153, 4, 1, 1), net_row(2, 1e12, 153, 4, 1, 1), net_row(3, OLE_2017, 999, 4, 1, 1)],
        ),
    ]
    found = said(tmp_path, tables, monkeypatch)
    records = of(found, "r")
    assert [r["ts"] for r in records] == [None, None, 1_509_881_520_000]
    assert records[2]["data"]["app"] == "" and records[2]["data"]["app_id"] == 999
    notes = {n["reason"]: n for n in of(found, "note")}
    assert (
        notes["row without a usable time"]["count"] == 2 and "1 of them" in notes["row without a usable time"]["detail"]
    )
    assert notes["id not in the ids table"]["count"] == 1
    assert notes["table not in the database"]["detail"].startswith(APPS)
    assert of(found, "end")[0]["in_file"] == 3 and not of(found, "skip")


def test_a_row_libesedb_cannot_read_is_a_skip_and_the_others_are_read(tmp_path, monkeypatch):
    rows = [
        net_row(1, OLE_2017, 153, 4, 1, 1),
        OSError("libesedb_page: invalid page checksum"),
        net_row(3, OLE_2017, 153, 4, 1, 1),
    ]
    found = said(tmp_path, [IDS, Table(NET, NET_COLUMNS, rows)], monkeypatch)
    assert len(of(found, "r")) == 2
    (skip,) = of(found, "skip")
    assert skip["reason"] == "row cannot be read" and skip["lost"] == 1 and "row 1 of 3" in skip["detail"]
    assert of(found, "end")[0]["in_file"] == 3


def test_many_unreadable_rows_are_said_one_by_one_up_to_a_limit_then_together(tmp_path, monkeypatch):
    rows = [OSError("bad page")] * 60
    found = said(tmp_path, [IDS, Table(NET, NET_COLUMNS, rows)], monkeypatch)
    skips = of(found, "skip")
    assert len(skips) == srum.MAX_SKIPS + 1
    assert sum(skip["lost"] for skip in skips) == 60 and skips[-1]["reason"] == "more rows that cannot be read"


def test_a_table_longer_than_the_limit_is_cut_and_the_rest_is_lost(tmp_path, monkeypatch):
    monkeypatch.setattr(srum, "MAX_ROWS", 3)
    rows = [net_row(i, OLE_2017, 153, 4, 1, 1) for i in range(1, 8)]
    found = said(tmp_path, [IDS, Table(NET, NET_COLUMNS, rows)], monkeypatch)
    assert len(of(found, "r")) == 3
    (skip,) = of(found, "skip")
    assert skip["reason"] == "row limit reached" and skip["lost"] == 4 and "first 3 of 7" in skip["detail"]
    assert of(found, "end")[0]["in_file"] == 7


def test_a_database_that_was_not_closed_cleanly_says_the_newest_rows_may_be_missing(tmp_path, monkeypatch):
    found = said(tmp_path, both(), monkeypatch, state=2)
    (note,) = [n for n in of(found, "note") if n["reason"] == "database not closed cleanly"]
    assert "dirty shutdown" in note["detail"] and "not replayed" in note["detail"] and "newest rows" in note["detail"]
    assert len(of(found, "r")) == 3


def test_a_missing_ids_table_and_a_table_without_its_columns_are_said(tmp_path, monkeypatch):
    found = said(tmp_path, [Table(NET, NET_COLUMNS, [net_row(1, OLE_2017, 153, 4, 1, 1)])], monkeypatch)
    assert any(n["reason"] == "ids table missing" for n in of(found, "note"))
    assert of(found, "r")[0]["data"]["app"] == ""
    odd = Table(NET, [("AutoIncId", 4), ("Other", 4)], [[i32(1), i32(2)]])
    found = said(tmp_path, [IDS, odd], monkeypatch)
    (skip,) = of(found, "skip")
    assert skip["reason"] == "table has not the columns it should" and skip["lost"] == 1 and not of(found, "r")


def test_a_table_that_cannot_be_opened_is_a_skip(tmp_path, monkeypatch):
    class Broken(Table):
        @property
        def number_of_records(self) -> int:
            raise OSError("libesedb: unable to read the table")

    found = said(tmp_path, [IDS, Broken(NET, NET_COLUMNS, [])], monkeypatch)
    (skip,) = of(found, "skip")
    assert skip["reason"] == "table cannot be opened" and NET in skip["detail"]


def test_a_file_that_is_not_an_ese_database_is_a_skip(tmp_path):
    path = tmp_path / "x"
    path.write_bytes(b"MZ" + b"\x00" * 5000)
    out = io.BytesIO()
    srum.parse(str(path), Context(out, {}), srum.SOURCES[0])
    found = [json.loads(line) for line in out.getvalue().splitlines()]
    assert of(found, "skip")[0]["reason"] == "not an ESE database" and of(found, "end")[0]["in_file"] is None


def test_a_database_libesedb_refuses_is_a_skip(tmp_path, monkeypatch):
    path = ese_file(tmp_path)

    def refuse(_path):
        raise ValueError("libesedb_file_open: invalid file header")

    monkeypatch.setattr(srum, "_open_db", refuse)
    out = io.BytesIO()
    srum.parse(path, Context(out, {}), srum.SOURCES[0])
    found = [json.loads(line) for line in out.getvalue().splitlines()]
    assert (
        of(found, "skip")[0]["reason"] == "database cannot be opened"
        and "invalid file header" in of(found, "skip")[0]["detail"]
    )


def test_sniff_by_the_ese_header_and_the_name(tmp_path, monkeypatch):
    path = ese_file(tmp_path)
    head = open(path, "rb").read(4096)
    assert srum.sniff(path, "SRUDB.dat", head) == "windows.network.srum-network"
    assert srum.sniff(path, "C:\\Windows\\System32\\sru\\srudb.dat", head) == "windows.network.srum-network"
    # Another name: the file is opened and must hold the ids table.
    monkeypatch.setattr(srum, "_open_db", lambda _path: Db([IDS]))
    assert srum.sniff(path, "copy.bin", head) == "windows.network.srum-network"
    monkeypatch.setattr(srum, "_open_db", lambda _path: Db([Table("MSysObjects", [], [])]))
    assert srum.sniff(path, "NTDS.dit", head) is None
    assert srum.sniff(path, "SRUDB.dat", head[:4] + b"MZMZ" + head[8:]) is None
    streaming = ese_file(tmp_path, kind=1)
    assert srum.sniff(streaming, "SRUDB.dat", open(streaming, "rb").read(4096)) is None


def test_the_decoding_of_values_ids_times_and_names():
    assert (
        srum.decode_value(4, struct.pack("<i", -5)) == -5
        and srum.decode_value(14, struct.pack("<I", 2**32 - 1)) == 2**32 - 1
    )
    assert srum.decode_value(15, struct.pack("<q", 2**40)) == 2**40 and srum.decode_value(2, b"\x07") == 7
    assert srum.decode_value(8, struct.pack("<d", 1.5)) == 1.5 and srum.decode_value(4, None) is None
    assert srum.decode_value(4, b"\x01\x02") == "0102"  # a size the type does not have: kept as hex, never lost
    assert srum.decode_value(12, b"abc\x00") == "abc" and srum.decode_value(9, b"\x01\xff") == "01ff"
    assert srum.ole_ms(25569.0) == 0 and srum.ole_ms(OLE_2017) == 1_509_881_520_000
    for bad in (0.0, None, math.nan, math.inf, 1e12, -1e12, "1"):
        assert srum.ole_ms(bad) is None
    assert (
        srum.sid_text(SID_SYSTEM) == "S-1-5-18"
        and srum.sid_text(b"\x01") == "01"
        and srum.sid_text(b"\x01\x0f\x00") == "010f00"
    )
    assert (
        srum.id_text(0, utf16("a.exe")) == "a.exe"
        and srum.id_text(3, SID_SYSTEM) == "S-1-5-18"
        and srum.id_text(0, None) == ""
    )
    assert (
        srum.snake("ForegroundNumberOfFlushes") == "foreground_number_of_flushes"
        and srum.snake("L2ProfileId") == "l2_profile_id"
    )


def test_view_shows_the_row_with_its_names(tmp_path, monkeypatch):
    path = ese_file(tmp_path)
    monkeypatch.setattr(srum, "_open_db", lambda _path: Db(both()))
    shown = srum.view(path, srum.SOURCES[0], {"table": "network", "index": 1, "id": 3496})
    rows = dict(shown["rows"])
    assert (
        rows["AutoIncId"] == "3496"
        and rows["AppId names"].endswith("svchost.exe")
        and rows["UserId names"].startswith("S-1-5-21")
    )
    assert rows["TimeStamp as a date"].startswith("2017-11-05T12:32")
    assert shown["where"] == {"table": "network", "index": 1} and NET in shown["title"]
    with pytest.raises(ViewError):
        srum.view(path, srum.SOURCES[0], {"table": "network", "index": 9})
    with pytest.raises(BadLocator):
        srum.view(path, srum.SOURCES[0], {"table": "nothing", "index": 0})
    with pytest.raises(BadLocator):
        srum.view(path, srum.SOURCES[0], {"table": "apps"})
    monkeypatch.setattr(srum, "_open_db", lambda _path: Db([IDS]))
    with pytest.raises(ViewError):
        srum.view(path, srum.SOURCES[0], {"table": "apps", "index": 0})


@pytest.mark.skipif(not os.environ.get("NIK_SRUDB_SAMPLE"), reason="no real SRUDB.dat named in NIK_SRUDB_SAMPLE")
def test_a_real_database_when_one_is_given():
    path = os.environ["NIK_SRUDB_SAMPLE"]
    out = io.BytesIO()
    srum.parse(path, Context(out, {"host": "REAL"}), srum.SOURCES[0])
    found = [json.loads(line) for line in out.getvalue().splitlines()]
    end = of(found, "end")[0]
    sources = {r["src"] for r in of(found, "r")}
    assert sources == set(srum.SOURCES) and end["read"] == end["in_file"] - sum(s["lost"] for s in of(found, "skip"))
    shown = srum.view(path, srum.SOURCES[0], of(found, "r")[0]["loc"])
    assert shown["rows"]
